   await check('Click-learned image opacity changes actual compositor output',async e=>{await assign('[data-overlay-key="opacity"]',22);await message(22,0);assert(image.opacity===0,'Image opacity not zero');e.off=await frame('image-midi-opacity-zero');await message(22,127);assert(image.opacity===1,'Image opacity not one');e.on=await frame('image-midi-opacity-one');assert(e.off.pixel[0]<245&&e.on.pixel[0]>245,'Image opacity did not change pixels');});
   await check('Mapped image routing moves metadata and decoded pixels across all three targets',async e=>{await message(21,0);for(const [target,number]of [['left',23],['right',24],['master',25]]){await assign('[data-overlay-route="'+target+'"]',number);await message(number,0);await message(number,127);assert(state.video.overlays[target].some(x=>x.id===image.id),'Metadata failed '+target);assert($('#video-overlay-target').value===target,'Editor selection failed '+target);e[target]=await frame('routed-image-'+target);}assert(e.left.pixel[0]>245&&e.right.pixel[0]<245&&e.master.pixel[0]>245,'Decoded image ownership/output not preserved');});
