async function init(){const parsed=new DOMParser().parseFromString(await(await fetch('index.html')).text(),'text/html');for(const e of [...parsed.body.children])if(e.tagName!=='SCRIPT')document.body.append(e);await import('./app.js');await until(()=>window.openPlay?.state.decks[0].track,'Actual app');app=window.openPlay;$('#overlay-run').disabled=false;$('#overlay-run').textContent='Run actual overlay and assignment checks';$('#overlay-status').textContent='Ready';}
$('#overlay-run').onclick=async()=>{if(hasRun)return;hasRun=true;const button=$('#overlay-run');button.disabled=true;try{await run();}catch(e){$('#overlay-status').textContent='Harness error: '+e.message;}finally{button.disabled=true;}};init().catch(e=>$('#overlay-status').textContent='Load failed: '+e.message);
